def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    row_tiles = [(row_bounds[i] + 1, row_bounds[i + 1]) for i in range(len(row_bounds) - 1)]
    col_tiles = [(col_bounds[i] + 1, col_bounds[i + 1]) for i in range(len(col_bounds) - 1)]

    divider_cells = set()
    for r in sep_rows:
        for c in range(w):
            divider_cells.add((r, c))
    for c in sep_cols:
        for r in range(h):
            divider_cells.add((r, c))

    from collections import Counter
    counts = Counter(
        grid[r][c] for r in range(h) for c in range(w)
        if (r, c) not in divider_cells
    )
    background = counts.most_common(1)[0][0]

    template = None
    for r0, r1 in row_tiles:
        for c0, c1 in col_tiles:
            tile = [row[c0:c1] for row in grid[r0:r1]]
            if any(v != background for row in tile for v in row):
                template = tile
                break
        if template is not None:
            break

    out = [row[:] for row in grid]
    if template is None:
        return out

    for r0, r1 in row_tiles:
        for c0, c1 in col_tiles:
            for dr in range(r1 - r0):
                for dc in range(c1 - c0):
                    out[r0 + dr][c0 + dc] = template[dr][dc]
    return out
